#!/usr/bin/env python3
"""Build the hosted RC2FX update history and its JSON feed.

Sources, each written once:

- ``CHANGELOG.md``: the app release notes git-cliff generates during release
  preparation. One section per stable app version.
- ``docs/updates/source/mixer-notes.md``: curated notes for RC2FX mixer
  software versions. A version without a section stays unknown; notes are
  never invented.
- ``config/mixer-release.json`` at each published app release's tag: the
  mixer software that app bundled and its control protocol version.
- GitHub's releases API: published app and standalone `mixer-v` releases.
  Drafts and pre-releases are never listed, even when a release tag or a
  CHANGELOG section already exists.

Outputs:

- ``docs/updates/app.md`` and ``docs/updates/mixer.md``: readable, cumulative
  histories with stable ``#vX.Y.Z`` anchors.
- ``docs/public/updates.json``: the feed the app reads.

The JSON contract is versioned by ``schemaVersion``. Adding fields is safe;
a breaking change needs a new feed URL.
"""

import argparse
import json
import os
from dataclasses import dataclass, field
from datetime import date as Date
from pathlib import Path
import re
import subprocess
import sys
import tomllib
import urllib.error
import urllib.request


REPOSITORY = "ibanks42/rc2fx"
FEED_SCHEMA_VERSION = 1
MAX_NOTES_BYTES = 64 * 1024
MAX_FEED_BYTES = 4 * 1024 * 1024
MAX_API_PAGE_BYTES = 16 * 1024 * 1024
API_PAGE_SIZE = 100
MAX_API_PAGES = 10
HTTP_TIMEOUT = 20
USER_AGENT = "rc2fx-docs-update-history"

STABLE = re.compile(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$")
SECTION = re.compile(r"^## \[([^\]]+)\](?: - (\d{4}-\d{2}-\d{2}))?\s*$")
CHANGELOG_FOOTER = re.compile(r"\n?<!-- generated by git-cliff -->\s*$")


class Problem(Exception):
    """A source cannot produce an honest history; stop the build."""


@dataclass(frozen=True)
class Section:
    version: str
    date: str | None
    body: str


@dataclass(frozen=True)
class Mapping:
    mixer_version: str | None
    protocol_version: int | None
    downloads_mixer: bool = False


@dataclass(frozen=True)
class Published:
    version: str
    date: str
    kind: str = "app"


@dataclass(frozen=True)
class AppRelease:
    version: str
    date: str
    notes: str | None
    mixer_version: str | None
    protocol_version: int | None
    downloads_mixer: bool = False

    def feed_entry(self):
        return {
            "version": self.version,
            "date": self.date,
            "notesMarkdown": self.notes,
            "releaseUrl": release_url(self.version),
            "mixerVersion": self.mixer_version,
            "protocolVersion": self.protocol_version,
            "downloadsMixer": self.downloads_mixer,
        }


@dataclass(frozen=True)
class MixerRelease:
    version: str
    date: str | None
    notes: str | None
    first_app_version: str | None

    def feed_entry(self):
        return {
            "version": self.version,
            "date": self.date,
            "notesMarkdown": self.notes,
            "firstAppVersion": self.first_app_version,
        }


@dataclass
class Bundle:
    feed: dict
    app_page: str
    mixer_page: str
    warnings: list[str] = field(default_factory=list)


def version_tuple(version):
    if not isinstance(version, str) or not STABLE.fullmatch(version):
        raise Problem(f"not a stable MAJOR.MINOR.PATCH version: {version!r}")
    return tuple(int(part) for part in version.split("."))


def release_url(version):
    return f"https://github.com/{REPOSITORY}/releases/tag/v{version}"


def parse_sections(text, source, dated):
    """Read ``## [VERSION] - DATE`` sections, preserving their Markdown body."""
    text = CHANGELOG_FOOTER.sub("", text)
    sections = {}
    current = None
    body = []

    def finish():
        if current is None:
            return
        version, section_date = current
        notes = "\n".join(body).strip()
        if dated and section_date is None:
            raise Problem(f"{source}: {version} has no date")
        sections[version] = Section(version, section_date, notes)

    for line in text.splitlines():
        match = SECTION.match(line)
        if match:
            finish()
            version, section_date = match.group(1), match.group(2)
            if version == "unreleased":
                current = None
                body = []
                continue
            version_tuple(version)
            if version in sections:
                raise Problem(f"{source}: {version} appears more than once")
            current = (version, section_date)
            body = []
            continue
        if current is not None:
            body.append(line)
    finish()

    for section in sections.values():
        if not section.body:
            raise Problem(f"{source}: {section.version} has no notes")
        check_notes_size(section.body, source, section.version)
    return sections


def check_notes_size(notes, source, version):
    size = len(notes.encode("utf-8"))
    if size > MAX_NOTES_BYTES:
        raise Problem(
            f"{source}: {version} notes are {size} bytes; "
            f"the client supports at most {MAX_NOTES_BYTES}"
        )


def parse_changelog(path):
    if not path.is_file():
        raise Problem(f"{path}: missing")
    return parse_sections(path.read_text(), str(path), dated=True)


def parse_mixer_notes(path):
    if not path.is_file():
        return {}
    return parse_sections(path.read_text(), str(path), dated=False)


def tag_mapping(root, version):
    """Read an app release's bundled mixer manifest from its tag.

    A published release always has a tag, so a missing tag is an error: a
    checkout without tags must not silently turn the whole mixer history
    unknown. A tag that predates the manifest is explicit unknown instead.
    """
    root = Path(root)
    if not (root / ".git").exists():
        raise Problem(
            "reading bundled mixer versions needs a git checkout with release tags"
        )
    ref = f"refs/tags/v{version}"
    try:
        verify = subprocess.run(
            ["git", "-C", str(root), "rev-parse", "--verify", "--quiet", ref],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except OSError as error:
        raise Problem(f"cannot run git: {error}") from error
    if verify.returncode != 0:
        raise Problem(
            f"v{version} is published but {ref} is missing; fetch release tags "
            "(for example fetch-depth: 0)"
        )
    try:
        app_manifest = subprocess.check_output(
            ["git", "-C", str(root), "show", f"{ref}:crates/rc2fx-app/Cargo.toml"],
            stderr=subprocess.DEVNULL, text=True,
        )
    except subprocess.CalledProcessError:
        app_manifest = None
    if app_manifest is not None:
        try:
            features = tomllib.loads(app_manifest).get("features", {})
        except tomllib.TOMLDecodeError as error:
            raise Problem(f"v{version}: invalid app manifest: {error}") from error
        if "embedded" in features and "embedded" not in features.get("default", []):
            return Mapping(None, None, downloads_mixer=True)
    try:
        raw = subprocess.check_output(
            ["git", "-C", str(root), "show", f"{ref}:config/mixer-release.json"],
            stderr=subprocess.DEVNULL,
            text=True,
        )
    except subprocess.CalledProcessError:
        # The tag predates the manifest; the mapping is unknown, not missing.
        return Mapping(None, None)
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as error:
        raise Problem(f"v{version}: config/mixer-release.json: {error}") from error
    if not isinstance(data, dict):
        raise Problem(f"v{version}: config/mixer-release.json is not an object")
    mixer = data.get("version")
    version_tuple(mixer)
    protocol = data.get("protocolVersion")
    if protocol is not None and (
        not isinstance(protocol, int) or isinstance(protocol, bool) or protocol < 1
    ):
        raise Problem(f"v{version}: config/mixer-release.json has an invalid protocolVersion")
    return Mapping(mixer, protocol)


def normalize_published(entries, source):
    """Keep published stable app and standalone mixer releases."""
    by_version = {}
    for entry in entries:
        if not isinstance(entry, dict):
            raise Problem(f"{source}: a release is not an object")
        if entry.get("draft") or entry.get("prerelease"):
            continue
        tag = entry.get("tag_name")
        if not isinstance(tag, str):
            continue
        if tag.startswith("mixer-v"):
            kind, version = "mixer", tag[len("mixer-v"):]
        elif tag.startswith("v"):
            kind, version = "app", tag[1:]
        else:
            continue
        if not STABLE.fullmatch(version):
            continue
        published_at = entry.get("published_at")
        if not isinstance(published_at, str) or len(published_at) < 10:
            raise Problem(f"{source}: {tag} has no publication date")
        try:
            Date.fromisoformat(published_at[:10])
        except ValueError as error:
            raise Problem(f"{source}: {tag} has an invalid publication date") from error
        if (kind, version) in by_version:
            raise Problem(f"{source}: {tag} appears more than once")
        by_version[kind, version] = Published(version, published_at[:10], kind)
    return sorted(by_version.values(), key=lambda p: version_tuple(p.version), reverse=True)


def fetch_published(repository=REPOSITORY):
    """Read every page of the repository's published releases."""
    token = os.environ.get("GH_TOKEN") or os.environ.get("GITHUB_TOKEN")
    entries = []
    for page in range(1, MAX_API_PAGES + 1):
        url = (
            f"https://api.github.com/repos/{repository}/releases"
            f"?per_page={API_PAGE_SIZE}&page={page}"
        )
        request = urllib.request.Request(
            url,
            headers={
                "Accept": "application/vnd.github+json",
                "X-GitHub-Api-Version": "2022-11-28",
                "User-Agent": USER_AGENT,
                **({"Authorization": f"Bearer {token}"} if token else {}),
            },
        )
        try:
            with urllib.request.urlopen(request, timeout=HTTP_TIMEOUT) as reply:
                body = reply.read(MAX_API_PAGE_BYTES + 1)
        except urllib.error.HTTPError as error:
            raise Problem(
                f"GitHub releases API answered HTTP {error.code} for page {page}"
            ) from error
        except (urllib.error.URLError, TimeoutError, OSError) as error:
            raise Problem(f"GitHub releases API is unreachable: {error}") from error
        if len(body) > MAX_API_PAGE_BYTES:
            raise Problem(f"GitHub releases API page {page} is too large")
        try:
            batch = json.loads(body)
        except json.JSONDecodeError as error:
            raise Problem(f"GitHub releases API page {page} is not JSON") from error
        if not isinstance(batch, list):
            raise Problem(f"GitHub releases API page {page} is not a list")
        entries.extend(batch)
        if len(batch) < API_PAGE_SIZE:
            return normalize_published(entries, "GitHub releases API")
    raise Problem(f"GitHub releases API has more than {API_PAGE_SIZE * MAX_API_PAGES} releases")


def sections_between(sections, lower, upper):
    """Sections whose version is strictly between two published versions."""
    lower_key = version_tuple(lower)
    upper_key = version_tuple(upper)
    results = [
        (version, section)
        for version, section in sections.items()
        if lower_key < version_tuple(version) < upper_key
    ]
    return sorted(results, key=lambda item: version_tuple(item[0]))


def composed_notes(section, folded, label, source):
    """A release's own notes plus the prepared versions folded into it."""
    parts = []
    for version, prepared in folded:
        parts.append(
            f"**Prepared as {label}{version}, not published.**\n\n{prepared.body}"
        )
    parts.append(section.body)
    notes = "\n\n".join(parts)
    check_notes_size(notes, source, section.version)
    return notes


def app_release_notes(version, changelog, published, newest, warnings):
    """Notes for one published app release, with abandoned drafts folded in."""
    own = changelog.get(version)
    index = next(i for i, p in enumerate(published) if p.version == version)
    older = published[index + 1].version if index + 1 < len(published) else None
    folded = sections_between(changelog, older, version) if own and older else []
    if own is None:
        if newest:
            raise Problem(
                f"v{version} is the newest published release but CHANGELOG.md "
                f"has no section for it"
            )
        if older and sections_between(changelog, older, version):
            warnings.append(
                f"v{version} has no Notes section, so prepared notes between "
                f"{older} and {version} could not be attached"
            )
        return None
    return composed_notes(own, folded, "v", "CHANGELOG.md")


def build_bundle(root, published, mappings=None):
    """Build the feed and both history pages from the repository sources.

    ``mappings`` is an optional app version to :class:`Mapping` override for
    tests. Without it, every published release's tag supplies the mapping.
    """
    root = Path(root)
    changelog = parse_changelog(root / "CHANGELOG.md")
    mixer_notes = parse_mixer_notes(root / "docs/updates/source/mixer-notes.md")
    warnings = []
    standalone = {release.version: release for release in published if release.kind == "mixer"}
    published = [release for release in published if release.kind == "app"]

    apps = []
    first_app_for_mixer = {}
    for release in published:
        if mappings is not None:
            mapping = mappings.get(release.version, Mapping(None, None))
        else:
            mapping = tag_mapping(root, release.version)
        if mapping.mixer_version is None and not mapping.downloads_mixer:
            warnings.append(
                f"v{release.version} has no recorded bundled mixer version"
            )
        apps.append(
            AppRelease(
                release.version,
                release.date,
                app_release_notes(
                    release.version,
                    changelog,
                    published,
                    release.version == published[0].version,
                    warnings,
                ),
                mapping.mixer_version,
                mapping.protocol_version,
                mapping.downloads_mixer,
            )
        )
        if mapping.mixer_version is not None:
            first = first_app_for_mixer.get(mapping.mixer_version)
            if first is None or version_tuple(release.version) < version_tuple(first.version):
                first_app_for_mixer[mapping.mixer_version] = release

    shipped_ascending = sorted(first_app_for_mixer.keys() | standalone.keys(), key=version_tuple)
    mixers = []
    folded_mixer_versions = set()
    for index, version in enumerate(shipped_ascending):
        first = first_app_for_mixer.get(version)
        independent = standalone.get(version)
        own = mixer_notes.get(version)
        older = shipped_ascending[index - 1] if index else None
        folded = sections_between(mixer_notes, older, version) if own and older else []
        folded_mixer_versions.update(prepared for prepared, _ in folded)
        if own is None:
            notes = None
            if older and sections_between(mixer_notes, older, version):
                warnings.append(
                    f"mixer {version} has no Notes section, so prepared notes "
                    f"between {older} and {version} could not be attached"
                )
        else:
            notes = composed_notes(
                own, folded, "mixer ", "docs/updates/source/mixer-notes.md"
            )
        date = min(release.date for release in (first, independent) if release is not None)
        mixers.append(MixerRelease(version, date, notes, first.version if first else None))

    for version in mixer_notes:
        if version not in shipped_ascending and version not in folded_mixer_versions:
            warnings.append(
                f"mixer {version} has notes but no published mixer release or app bundle"
            )

    mixers.sort(key=lambda m: version_tuple(m.version), reverse=True)
    app_complete = all(release.notes is not None for release in apps)
    mappings_missing = any(release.mixer_version is None and not release.downloads_mixer for release in apps)
    notes_missing = any(release.notes is None for release in mixers)
    app_latest = apps[0].version if apps else None
    app_history_start = apps[-1].version if apps else None
    mixer_latest = mixers[0].version if mixers else None
    mixer_history_start = mixers[-1].version if mixers else None
    feed = {
        "schemaVersion": FEED_SCHEMA_VERSION,
        "app": {
            "latest": app_latest,
            "historyStart": app_history_start,
            "historyComplete": app_complete,
            "releases": [release.feed_entry() for release in apps],
        },
        "mixer": {
            "latest": mixer_latest,
            "historyStart": mixer_history_start,
            "historyComplete": not mappings_missing and not notes_missing,
            "releases": [release.feed_entry() for release in mixers],
        },
    }
    encoded = json.dumps(feed, indent=2, ensure_ascii=False).encode("utf-8")
    if len(encoded) > MAX_FEED_BYTES:
        raise Problem(
            f"updates.json is {len(encoded)} bytes; the client supports at most "
            f"{MAX_FEED_BYTES}"
        )
    return Bundle(
        feed=feed,
        app_page=render_app_page(apps, app_complete),
        mixer_page=render_mixer_page(mixers, mappings_missing, notes_missing),
        warnings=warnings,
    )


def render_app_page(apps, complete):
    lines = [
        "---",
        "title: App release history",
        "description: Every published RC2FX desktop app release and its notes.",
        "---",
        "",
        "# App release history",
        "",
        "Every published RC2FX desktop app release, newest first, with the notes",
        "published for it. **Settings › Versions** shows the notes between the app you",
        "have installed and the version offered.",
        "",
    ]
    if not apps:
        lines += ["No RC2FX app release has been published yet.", ""]
        return "\n".join(lines)
    if len(apps) == 1:
        boundary = f"This history lists the published app release: v{apps[0].version}."
    else:
        boundary = (
            f"This history lists every published app release from "
            f"v{apps[-1].version} to v{apps[0].version}."
        )
        if not complete:
            boundary += " Notes for some releases are unavailable."
    lines += [boundary, ""]
    for release in apps:
        lines += [f"## v{release.version}", ""]
        bundled = "unknown"
        if release.mixer_version is not None:
            bundled = f"[{release.mixer_version}](mixer.md#v{release.mixer_version})"
        lines += [
            f"Released {release.date}. "
            + ("Mixer software is downloaded separately. " if release.downloads_mixer
               else f"Bundled RC2FX mixer software: {bundled}. ")
            +
            f"[GitHub release]({release_url(release.version)}).",
            "",
        ]
        if release.notes is None:
            lines += ["No published notes are available for this release.", ""]
        else:
            lines += [release.notes, ""]
    return "\n".join(lines)


def render_mixer_page(mixers, mappings_missing, notes_missing):
    lines = [
        "---",
        "title: Mixer software history",
        "description: Published RC2FX mixer software versions.",
        "---",
        "",
        "# Mixer software history",
        "",
        "RC2FX mixer software is released independently of the desktop app. This",
        "history includes standalone releases and older app bundles, newest first.",
        "Newer mixer software can require a newer app first.",
        "",
    ]
    if not mixers:
        lines += ["No RC2FX mixer software history is known from published releases.", ""]
        return "\n".join(lines)
    if len(mixers) == 1:
        if mappings_missing:
            boundary = (
                f"This history starts at v{mixers[0].version}, the only mixer version "
                f"recorded by a published release. Some published app releases "
                f"don't record their bundled mixer software, so other versions may exist."
            )
        elif notes_missing:
            boundary = (
                f"This history records one mixer version, v{mixers[0].version}, but "
                f"its notes are unavailable."
            )
        else:
            boundary = (
                f"This history records the mixer version in published "
                f"releases: v{mixers[0].version}."
            )
    elif mappings_missing:
        boundary = (
            f"This history starts at v{mixers[-1].version}, the oldest mixer version "
            f"recorded by a published release, and ends at v{mixers[0].version}. "
            f"Some published app releases don't record their bundled mixer software, "
            f"so earlier versions may exist."
        )
    elif notes_missing:
        boundary = (
            f"This history records every mixer version in a published "
            f"release from v{mixers[-1].version} to v{mixers[0].version}, but notes "
            f"for some versions are unavailable."
        )
    else:
        boundary = (
            f"This history records every mixer version in a published "
            f"release from v{mixers[-1].version} to v{mixers[0].version}."
        )
    lines += [boundary, ""]
    for release in mixers:
        lines += [f"## v{release.version}", ""]
        when = f", released {release.date}" if release.date else ""
        if release.first_app_version is None:
            lines += [f"Standalone mixer release{when}. "
                      f"[GitHub release](https://github.com/{REPOSITORY}/releases/tag/mixer-v{release.version}).", ""]
        else:
            lines += [
                f"First bundled in RC2FX [{release.first_app_version}]"
                f"(app.md#v{release.first_app_version}). First published {release.date}.",
                "",
            ]
        if release.notes is None:
            lines += ["No published notes are available for this mixer version.", ""]
        else:
            lines += [release.notes, ""]
    return "\n".join(lines)


def write_bundle(root, bundle):
    root = Path(root)
    outputs = {
        root / "docs/updates/app.md": bundle.app_page,
        root / "docs/updates/mixer.md": bundle.mixer_page,
        root / "docs/public/updates.json": json.dumps(
            bundle.feed, indent=2, ensure_ascii=False
        )
        + "\n",
    }
    for path, text in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)
    return [str(path.relative_to(root)) for path in outputs]


def load_published(path):
    entries = json.loads(Path(path).read_text())
    if not isinstance(entries, list):
        raise Problem(f"{path}: expected a JSON list of GitHub releases")
    return normalize_published(entries, str(path))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--root",
        type=Path,
        default=Path(__file__).resolve().parents[2],
        help="repository root (default: the checkout this script is in)",
    )
    parser.add_argument(
        "--published-json",
        type=Path,
        help="read GitHub's release list from this file instead of the API (tests)",
    )
    args = parser.parse_args(argv)
    try:
        published = (
            load_published(args.published_json)
            if args.published_json
            else fetch_published()
        )
        bundle = build_bundle(args.root, published)
        wrote = write_bundle(args.root, bundle)
    except Problem as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    for warning in bundle.warnings:
        print(f"warning: {warning}", file=sys.stderr)
    app = bundle.feed["app"]
    mixer = bundle.feed["mixer"]
    print(
        f"wrote {', '.join(wrote)}: "
        f"{len(app['releases'])} app releases and {len(mixer['releases'])} mixer versions"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
